"""Paged-KV metadata dispatch via CuTe cubin bundle."""

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled, warn_and_run_fallback
from kestrel_kernels.paged_kv_metadata_ops.fallback import (
    build_paged_kv_metadata_torch,
)

_family = CubinFamily("paged_kv_metadata")
_THREADS = 128
_ENABLE_JIT = is_cute_jit_enabled()
if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


def _variant_key(batch_idx: torch.Tensor) -> str:
    if batch_idx.dtype == torch.int32:
        return "batch_i32"
    if batch_idx.dtype == torch.int64:
        return "batch_i64"
    raise ValueError(f"batch_idx must be int32 or int64, got {batch_idx.dtype}")


def _ensure_variant(variant_key: str, page_table: torch.Tensor) -> bool:
    device_index = int(page_table.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if _family.is_available(variant_key):
        return True
    if not _ENABLE_JIT:
        return False
    batch_idx_dtype = "i32" if variant_key == "batch_i32" else "i64"
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_cubin_bundles._compile_paged_kv_metadata(batch_idx_dtype),
        block_x=_THREADS,
        device_index=device_index,
    )
    return True


def _validate(
    page_table: torch.Tensor,
    batch_idx: torch.Tensor,
    input_pos: torch.Tensor,
    out_page_table: torch.Tensor,
    out_seqused_k: torch.Tensor,
    page_size: int,
) -> None:
    if page_size <= 0:
        raise ValueError(f"page_size must be positive, got {page_size}")
    if page_table.ndim != 2:
        raise ValueError("page_table must be 2D")
    if batch_idx.ndim != 1:
        raise ValueError("batch_idx must be 1D")
    if input_pos.ndim != 1:
        raise ValueError("input_pos must be 1D")
    if batch_idx.shape[0] != input_pos.shape[0]:
        raise ValueError("batch_idx and input_pos must have the same length")
    if out_page_table.ndim != 2:
        raise ValueError("out_page_table must be 2D")
    if out_seqused_k.ndim != 1:
        raise ValueError("out_seqused_k must be 1D")

    batch_size = int(batch_idx.shape[0])
    n_pages = int(page_table.shape[1])
    if out_page_table.shape[0] < batch_size:
        raise ValueError("out_page_table has insufficient batch capacity")
    if out_page_table.shape[1] < n_pages:
        raise ValueError("out_page_table has insufficient page capacity")
    if out_seqused_k.shape[0] < batch_size:
        raise ValueError("out_seqused_k has insufficient batch capacity")

    if page_table.dtype != torch.int32:
        raise ValueError("page_table must be int32")
    if out_page_table.dtype != torch.int32:
        raise ValueError("out_page_table must be int32")
    if out_seqused_k.dtype != torch.int32:
        raise ValueError("out_seqused_k must be int32")
    if input_pos.dtype != torch.int32:
        raise ValueError("input_pos must be int32")
    _variant_key(batch_idx)

    device = page_table.device
    if batch_idx.device != device or input_pos.device != device:
        raise ValueError(
            f"batch_idx/input_pos must live on {device}, "
            f"got {batch_idx.device}/{input_pos.device}"
        )
    if out_page_table.device != device or out_seqused_k.device != device:
        raise ValueError("out_page_table/out_seqused_k must live on page_table.device")
    if page_table.stride(-1) != 1:
        raise ValueError("page_table must be contiguous in the last dimension")
    if out_page_table.stride(-1) != 1:
        raise ValueError("out_page_table must be contiguous in the last dimension")


def build_paged_kv_metadata(
    page_table: torch.Tensor,
    batch_idx: torch.Tensor,
    input_pos: torch.Tensor,
    out_page_table: torch.Tensor,
    out_seqused_k: torch.Tensor,
    page_size: int,
) -> None:
    """Build compact paged-KV metadata for an active batch.

    Writes:
      - ``out_page_table[b, p] = page_table[batch_idx[b], p]`` for pages
        used by ``input_pos[b] + 1``; unused tail entries are left unchanged.
      - ``out_seqused_k[b] = input_pos[b] + 1``.
    """
    page_size = int(page_size)
    _validate(page_table, batch_idx, input_pos, out_page_table, out_seqused_k, page_size)
    batch_size = int(batch_idx.shape[0])
    if batch_size == 0:
        return

    if not batch_idx.is_contiguous():
        batch_idx = batch_idx.contiguous()
    if not input_pos.is_contiguous():
        input_pos = input_pos.contiguous()

    variant_key = _variant_key(batch_idx)
    n_pages = int(page_table.shape[1])
    if page_table.device.type == "cuda" and _ensure_variant(variant_key, page_table):
        launcher = _family.resolve_dispatch(
            page_table,
            variant_key=variant_key,
            grid_x=ceil_div(n_pages, _THREADS),
            grid_y=batch_size,
        )
        launcher(
            page_table,
            batch_idx,
            input_pos,
            out_page_table,
            out_seqused_k,
            page_size,
        )
        return

    warn_and_run_fallback(
        kernel_key="build_paged_kv_metadata",
        message=(
            "kestrel-kernels: using PyTorch fallback for build_paged_kv_metadata "
            "(no CuTe cubin bundle available for this device/runtime)."
        ),
        fallback=build_paged_kv_metadata_torch,
        args=(page_table, batch_idx, input_pos, out_page_table, out_seqused_k, page_size),
    )


__all__ = ["build_paged_kv_metadata"]
